// engine.js: the browser's copy of src/ffabasis/engine.py, function for function.
//
// tools/validate-engine.mjs holds the two within 1e-9 (relative) on every case
// in data/fixtures/engine_cases.json, generated by scripts/gen_fixtures.py from
// the Python engine. No figure lives here: configure() takes the contract and
// convention constants from data/engine.json, written from the Python module.

let C = null;

export function configure(constants) {
  C = Object.freeze({ ...constants });
  return C;
}

function need() {
  if (C === null) throw new Error("engine.js: call configure() with data/engine.json first");
  return C;
}

// Left to right addition, the order the Python engine adds in.
function total(values) {
  let sum = 0.0;
  for (const value of values) sum += value;
  return sum;
}

// ---------------------------------------------------------------- calendar

export function is_leap(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

export function days_in_month(year, month) {
  if (month === 2) return is_leap(year) ? 29 : 28;
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

export function parse_date(iso) {
  return [Number(iso.slice(0, 4)), Number(iso.slice(5, 7)), Number(iso.slice(8, 10))];
}

function pad2(n) {
  return String(n).padStart(2, "0");
}

export function month_key(year, month) {
  return `${String(year).padStart(4, "0")}-${pad2(month)}`;
}

export function add_months(month, n) {
  const year = Number(month.slice(0, 4));
  const mon = Number(month.slice(5, 7));
  const index = year * 12 + (mon - 1) + n;
  return month_key(Math.floor(index / 12), (((index % 12) + 12) % 12) + 1);
}

export function months_between(earlier, later) {
  return (Number(later.slice(0, 4)) * 12 + Number(later.slice(5, 7))) -
    (Number(earlier.slice(0, 4)) * 12 + Number(earlier.slice(5, 7)));
}

export function quarter_of(month) {
  return `${month.slice(0, 4)}-Q${Math.floor((Number(month.slice(5, 7)) - 1) / 3) + 1}`;
}

export function quarter_months(quarter) {
  const year = Number(quarter.slice(0, 4));
  const q = Number(quarter.slice(6, 7));
  const first = (q - 1) * 3 + 1;
  return [0, 1, 2].map((i) => month_key(year, first + i));
}

export function month_days(start, total_days) {
  if (!(total_days > 0)) throw new Error("a voyage needs a positive number of days");
  let [year, month, day] = parse_date(start);
  let remaining = Number(total_days);
  const out = [];
  let first = true;
  while (remaining > 0) {
    const available = days_in_month(year, month) - (first ? day - 1 : 0);
    const span = available < remaining ? available : remaining;
    out.push({ month: month_key(year, month), days: span });
    remaining -= span;
    first = false;
    month += 1;
    if (month === 13) {
      month = 1;
      year += 1;
    }
  }
  return out;
}

// ---------------------------------------------------- settlement, baskets

export function settlement_average(values) {
  if (!values.length) throw new Error("no assessments to average");
  return total(values.map(Number)) / values.length;
}

export function settles_on(day, month, product) {
  const c = need();
  if (day.slice(0, 7) !== month) return false;
  if (product === "td3c" && month.slice(5, 7) === "12") return Number(day.slice(8, 10)) <= c.TD3C_DECEMBER_LAST_DAY;
  if (product === "5tc" || product === "td3c") return true;
  throw new Error(`unknown product ${product}`);
}

export function period_average(month_settlements, months) {
  return total(months.map((m) => Number(month_settlements[m]))) / months.length;
}

export function basket_of(day) {
  return day >= need().BASKET_182_FROM ? 182000 : 180000;
}

export function convert_basket(value_usd_day, from_t, to_t, day) {
  const c = need();
  if (from_t === to_t) return Number(value_usd_day);
  if (day < c.BASKET_182_FROM) throw new Error(`no 182,000 t basket before ${c.BASKET_182_FROM}`);
  if (from_t === 182000 && to_t === 180000) return Number(value_usd_day) - c.C5TC_180_DIFFERENTIAL_USD_DAY;
  if (from_t === 180000 && to_t === 182000) return Number(value_usd_day) + c.C5TC_180_DIFFERENTIAL_USD_DAY;
  throw new Error(`unknown basket pair ${from_t}, ${to_t}`);
}

// --------------------------------------------------- strips, basis, shape

export function strip_price(weights, prices) {
  const days = total(weights.map((w) => Number(w.days)));
  const value = total(weights.map((w) => Number(w.days) * Number(prices[w.month])));
  return value / days;
}

export function basis(ffa, spot) {
  return Number(ffa) - Number(spot);
}

export function shape(earlier, later) {
  if (later > earlier) return "contango";
  if (later < earlier) return "backwardation";
  return "flat";
}

export function gross_up(net_tce_usd_day, commission_pct) {
  return Number(net_tce_usd_day) / (1.0 - Number(commission_pct) / need().PERCENT);
}

export function net_share(commission_pct) {
  return 1.0 - Number(commission_pct) / need().PERCENT;
}

// ------------------------------------------------- the paper side of a voyage

export function hedge_lots(weights, commission_pct, ratio) {
  const keep = net_share(commission_pct);
  return weights.map((w) => ({ month: w.month, days: Number(w.days) * keep * Number(ratio) }));
}

export function paper_pnl(role, ffa, settlement, size) {
  if (role === "owner") return (Number(ffa) - Number(settlement)) * Number(size);
  if (role === "charterer") return (Number(settlement) - Number(ffa)) * Number(size);
  throw new Error("role is owner or charterer");
}

export function strip_pnl(role, lots, ffa, settlement) {
  return total(lots.map((lot) => paper_pnl(role, ffa[lot.month], settlement[lot.month], lot.days)));
}

export function surprise(physical_gross, f0) {
  return Number(physical_gross) - Number(f0);
}

export function hedged_surprise(physical_gross, f0, s, ratio) {
  return (Number(physical_gross) - Number(f0)) - Number(ratio) * (Number(s) - Number(f0));
}

export function outcome(role, physical_rate, f0, s, days, commission_pct, ratio) {
  const keep = net_share(commission_pct);
  const size = Number(days) * keep * Number(ratio);
  const physical = Number(physical_rate) * Number(days) * keep;
  const paper = paper_pnl(role, f0, s, size);
  let totalUsd;
  let locked;
  if (role === "owner") {
    totalUsd = physical + paper;
    locked = Number(f0) * Number(days) * keep;
  } else {
    totalUsd = -physical + paper;
    locked = -Number(f0) * Number(days) * keep;
  }
  return {
    size_days: size,
    physical_usd: role === "owner" ? physical : -physical,
    paper_usd: paper,
    total_usd: totalUsd,
    locked_usd: locked,
    total_usd_day: totalUsd / Number(days),
    versus_locked_usd: totalUsd - locked,
  };
}

export function td3c_outcome(role, physical_usd_t, f0, s, tonnes, ratio) {
  const c = need();
  const size = Number(tonnes) * Number(ratio);
  const physical = Number(physical_usd_t) * Number(tonnes);
  const paper = paper_pnl(role, f0, s, size);
  const sign = role === "owner" ? 1.0 : -1.0;
  const totalUsd = sign * physical + paper;
  const locked = sign * Number(f0) * Number(tonnes);
  return {
    size_t: size,
    lots: size / c.TONNES_PER_LOT_TD3C,
    physical_usd: sign * physical,
    paper_usd: paper,
    total_usd: totalUsd,
    locked_usd: locked,
    versus_locked_usd: totalUsd - locked,
  };
}

export function ws_to_usd_t(ws_points, flat_rate_usd_t) {
  return Number(ws_points) / need().PERCENT * Number(flat_rate_usd_t);
}

export function implied_flat_rate(usd_t, ws_points) {
  return Number(usd_t) * need().PERCENT / Number(ws_points);
}
